namespace sv_5e334959150a4fd6b4f6617ca09be33e.Services;

public class Warehouse
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the currently
/// selected warehouse and notifies all subscribers when it changes.
/// Each user circuit gets its own instance, so selections are independent.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<Warehouse> _warehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public IReadOnlyList<Warehouse> AvailableWarehouses => _warehouses;

    public Warehouse CurrentWarehouse { get; private set; } = _warehouses[0];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = _warehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_5e334959150a4fd6b4f6617ca09be33e.Services;

/// <summary>
/// Scoped service (per-circuit) that provides low-stock alert counts and
/// coordinates polling with cross-component notifications. Each user gets
/// their own instance, so alert counts are independent per session.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should
    /// re-render to reflect the updated count.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component becomes visible and wants polling to run.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
                BeginPollingLoop();
        }
    }

    /// <summary>
    /// Call when a component is disposed or leaves the page.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
                CancelPolling();
        }
    }

    private void BeginPollingLoop()
    {
        CancelPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            // Fetch immediately on start, then every 10 seconds.
            await PollOnceAsync();

            try
            {
                while (await _timer.WaitForNextTickAsync(token))
                {
                    await PollOnceAsync();
                }
            }
            catch (OperationCanceledException) { }
        }, token);
    }

    private async Task PollOnceAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When the warehouse changes, immediately re-poll if polling is active.
        if (_subscriberCount > 0)
            await PollOnceAsync();
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        CancelPolling();
    }
}

