namespace sv_5e334959150a4fd6b4f6617ca09be33e.Services;

public class Warehouse
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the currently
/// selected warehouse and notifies all subscribers when it changes.
/// Each user circuit gets its own instance, so selections are independent.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<Warehouse> _warehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public IReadOnlyList<Warehouse> AvailableWarehouses => _warehouses;

    public Warehouse CurrentWarehouse { get; private set; } = _warehouses[0];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = _warehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

