﻿@page "/"
@rendermode InteractiveServer
@using sv_5e334959150a4fd6b4f6617ca09be33e.Services
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouse.Name</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger fs-3 fw-bold">
                    ⚠ @AlertService.CurrentLowStockCount items below minimum levels
                </span>
            }
            else
            {
                <span class="text-success fs-3 fw-bold">
                    ✓ All items above minimum levels
                </span>
            }
        </p>
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleStateChanged;
        AlertService.StartPolling();
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleStateChanged;
        AlertService.StopPolling();
    }
}

